INSERT INTO public.packages (name,slug,category,description,duration_minutes,total_questions,is_free,is_published)
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang manajer di Unit Pelaksana Pelayanan Pelanggan (UP3) PLN sedang menyusun target pendapatan dan jumlah pelanggan yang akan dilayani untuk tahun depan. Kegiatan yang dilakukan manajer tersebut merupakan bagian dari fungsi manajemen...','[{"key": "A", "text": "Organizing (Pengorganisasian)"}, {"key": "B", "text": "Planning (Perencanaan)"}, {"key": "C", "text": "Controlling (Pengendalian)"}, {"key": "D", "text": "Leading (Kepemimpinan)"}]'::jsonb,'A','Menyusun target pendapatan, jumlah pelanggan baru, dan rencana pengembangan jaringan untuk tahun depan adalah esensi dari fungsi perencanaan (planning). Ini adalah langkah awal dan fundamental dalam manajemen di mana manajer menetapkan "apa" yang ingin dicapai dan "bagaimana" cara mencapainya.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pembagian tugas kepada tim teknisi untuk melakukan pemeliharaan gardu listrik di beberapa lokasi yang berbeda adalah contoh konkret dari fungsi...','[{"key": "A", "text": "Planning"}, {"key": "B", "text": "Organizing"}, {"key": "C", "text": "Actuating"}, {"key": "D", "text": "Controlling"}]'::jsonb,'A','Fungsi organizing (pengorganisasian) melibatkan alokasi sumber daya, seperti menugaskan tim teknisi ke area tertentu, menentukan siapa melapor kepada siapa, dan membuat struktur departemen. Tujuannya adalah untuk menciptakan kerangka kerja yang efisien agar rencana dapat dieksekusi dengan baik.','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fungsi manajemen yang memastikan bahwa semua kegiatan yang dilaksanakan oleh PLN sesuai dengan standar dan target yang telah ditetapkan adalah...','[{"key": "A", "text": "Leading"}, {"key": "B", "text": "Planning"}, {"key": "C", "text": "Controlling"}, {"key": "D", "text": "Organizing"}]'::jsonb,'A','Fungsi controlling adalah proses untuk memastikan bahwa aktivitas aktual sesuai dengan aktivitas yang direncanakan. Di PLN, ini bisa berarti memantau realisasi pemakaian anggaran proyek terhadap rencana atau memeriksa apakah standar waktu respon gangguan pelanggan terpenuhi, lalu melakukan perbaikan jika ada penyimpangan.','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang supervisor di PLN memberikan arahan, motivasi, dan bimbingan kepada para stafnya agar dapat bekerja secara optimal untuk mencapai tujuan tim. Ini adalah implementasi dari fungsi...','[{"key": "A", "text": "Planning"}, {"key": "B", "text": "Organizing"}, {"key": "C", "text": "Leading"}, {"key": "D", "text": "Evaluating"}]'::jsonb,'A','Leading (kepemimpinan) adalah tentang bagaimana seorang manajer berinteraksi dan memengaruhi timnya. Ini mencakup pemberian arahan yang jelas, penyelesaian konflik, serta penciptaan lingkungan kerja yang positif untuk memotivasi karyawan agar memberikan kinerja terbaik mereka.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam manajemen, proses menetapkan tujuan dan cara terbaik untuk mencapainya dikenal sebagai...','[{"key": "A", "text": "Pengorganisasian"}, {"key": "B", "text": "Perencanaan"}, {"key": "C", "text": "Pengarahan"}, {"key": "D", "text": "Pengawasan"}]'::jsonb,'A','Perencanaan adalah fondasi dari semua fungsi manajemen lainnya. Tanpa rencana yang jelas mengenai tujuan (misalnya, meningkatkan rasio elektrifikasi) dan strategi, fungsi pengorganisasian, kepemimpinan, dan pengendalian tidak akan memiliki arah yang jelas.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Evaluasi laporan kinerja bulanan dari unit pembangkit untuk membandingkan output energi aktual dengan target yang direncanakan termasuk dalam fungsi...','[{"key": "A", "text": "Controlling"}, {"key": "B", "text": "Planning"}, {"key": "C", "text": "Organizing"}, {"key": "D", "text": "Leading"}]'::jsonb,'A','Kegiatan ini merupakan bagian vital dari fungsi controlling. Dengan membandingkan data aktual (output energi) dengan target yang ditetapkan dalam tahap perencanaan, manajemen dapat mengidentifikasi keberhasilan, kegagalan, atau area yang memerlukan perbaikan untuk periode operasional berikutnya.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah urutan yang paling logis dari fungsi-fungsi manajemen?','[{"key": "A", "text": "Planning -> Controlling -> Organizing -> Leading"}, {"key": "B", "text": "Planning -> Organizing -> Leading -> Controlling"}, {"key": "C", "text": "Organizing -> Planning -> Leading -> Controlling"}, {"key": "D", "text": "Leading -> Planning -> Organizing -> Controlling"}]'::jsonb,'A','Siklus ini (Planning, Organizing, Leading, Controlling - POLC) adalah kerangka kerja standar dalam manajemen. Perencanaan menetapkan peta jalan, pengorganisasian menyiapkan sumber daya (tim, anggaran, peralatan), kepemimpinan mengarahkan pelaksanaan, dan pengendalian memastikan perjalanan tetap di jalur yang benar menuju tujuan.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah unit proyek pembangunan transmisi baru di PLN terdiri dari insinyur, staf keuangan, dan ahli hukum yang melapor kepada manajer proyek dan juga kepada kepala departemen fungsional mereka masing-masing. Struktur organisasi yang paling sesuai untuk menggambarkan situasi ini adalah...','[{"key": "A", "text": "Struktur Fungsional"}, {"key": "B", "text": "Struktur Divisional"}, {"key": "C", "text": "Struktur Matriks"}, {"key": "D", "text": "Struktur Lini"}]'::jsonb,'A','Struktur matriks sering digunakan dalam organisasi berbasis proyek seperti PLN untuk pembangunan infrastruktur baru. Keuntungannya adalah fleksibilitas dan pemanfaatan ahli secara efisien lintas departemen, namun tantangan utamanya adalah potensi konflik karena karyawan memiliki dua atasan.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang pemimpin unit PLN yang cenderung mengambil keputusan sendiri tanpa banyak melibatkan bawahannya dan memberikan instruksi yang jelas untuk diikuti menerapkan gaya kepemimpinan...','[{"key": "A", "text": "Demokratis"}, {"key": "B", "text": "Otokratis"}, {"key": "C", "text": "Laissez-faire"}, {"key": "D", "text": "Transformasional"}]'::jsonb,'A','Gaya kepemimpinan otokratis (autocratic) adalah gaya di mana pemimpin membuat keputusan secara sepihak dengan sedikit atau tanpa masukan dari bawahan. Gaya ini bisa efektif dalam situasi darurat atau ketika keputusan cepat diperlukan, namun dalam jangka panjang dapat menurunkan motivasi dan kreativitas karyawan.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Gaya kepemimpinan yang berfokus pada pemberian inspirasi dan motivasi kepada karyawan untuk melampaui kepentingan pribadi demi kebaikan organisasi disebut...','[{"key": "A", "text": "Transaksional"}, {"key": "B", "text": "Transformasional"}, {"key": "C", "text": "Otokratis"}, {"key": "D", "text": "Demokratis"}]'::jsonb,'A','Pemimpin transformasional tidak hanya memberi perintah, tetapi juga bertindak sebagai panutan (role model) dan mentor. Mereka mendorong bawahan untuk melihat gambaran besar dan berkomitmen pada visi perusahaan, yang sangat penting di industri yang terus berkembang seperti ketenagalistrikan.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Di sebuah kantor layanan PLN yang situasinya dinamis dan membutuhkan keputusan cepat, manajer sering mengadakan rapat singkat untuk mendengar masukan dari tim sebelum mengambil keputusan akhir. Gaya kepemimpinan ini adalah...','[{"key": "A", "text": "Otokratis"}, {"key": "B", "text": "Laissez-faire"}, {"key": "C", "text": "Demokratis"}, {"key": "D", "text": "Karismatik"}]'::jsonb,'A','Dalam gaya demokratis, pemimpin tetap memegang tanggung jawab akhir atas keputusan, tetapi ia secara aktif mencari masukan dan ide dari anggota tim. Pendekatan ini dapat meningkatkan kualitas keputusan dan komitmen tim terhadap hasil akhir karena merasa dilibatkan.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kelemahan utama dari struktur organisasi fungsional adalah...','[{"key": "A", "text": "Kurangnya spesialisasi"}, {"key": "B", "text": "Kesulitan dalam koordinasi antar departemen"}, {"key": "C", "text": "Duplikasi sumber daya"}, {"key": "D", "text": "Rantai komando yang tidak jelas"}]'::jsonb,'A','Meskipun struktur fungsional (misalnya, departemen Keuangan, SDM, Teknik) mendorong spesialisasi yang mendalam, kelemahannya yang paling signifikan adalah "efek silo". Ini terjadi ketika departemen menjadi terlalu terisolasi dan kurang berkomunikasi satu sama lain, sehingga memperlambat proses yang membutuhkan kerjasama lintas-departemen.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menurut teori kepemimpinan situasional, pendekatan yang paling efektif bagi seorang pemimpin adalah...','[{"key": "A", "text": "Menggunakan satu gaya kepemimpinan secara konsisten"}, {"key": "B", "text": "Menyesuaikan gaya kepemimpinan dengan tingkat kesiapan (maturity) bawahan"}, {"key": "C", "text": "Berfokus sepenuhnya pada tugas (task-oriented)"}, {"key": "D", "text": "Berfokus sepenuhnya pada hubungan (relationship-oriented)"}]'::jsonb,'A','Teori ini menyarankan pemimpin untuk fleksibel. Misalnya, seorang teknisi baru mungkin membutuhkan gaya yang lebih mengarahkan (directing), sementara seorang insinyur senior yang berpengalaman mungkin lebih cocok dengan gaya mendelegasikan (delegating). Kunci efektivitasnya adalah diagnosis yang akurat terhadap tingkat kompetensi dan komitmen bawahan.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN membagi organisasinya berdasarkan wilayah geografis seperti Unit Induk Wilayah (UIW) Sumatera Barat, UIW Jawa Barat, dan seterusnya. Ini adalah contoh penerapan struktur organisasi...','[{"key": "A", "text": "Fungsional"}, {"key": "B", "text": "Matriks"}, {"key": "C", "text": "Divisional berdasarkan geografis"}, {"key": "D", "text": "Produk"}]'::jsonb,'A','Struktur divisional berdasarkan geografis seperti Unit Induk Wilayah (UIW) di PLN memungkinkan perusahaan untuk lebih responsif terhadap kebutuhan dan kondisi pasar lokal. Setiap divisi beroperasi seolah-olah bisnis kecil yang fokus pada wilayahnya, sehingga lebih lincah dalam pengambilan keputusan yang relevan dengan area tersebut.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses sistematis untuk mengumpulkan, menganalisis, dan mengevaluasi kinerja seorang karyawan terhadap standar pekerjaan yang telah ditetapkan di PLN disebut...','[{"key": "A", "text": "Rekrutmen"}, {"key": "B", "text": "Pelatihan dan Pengembangan"}, {"key": "C", "text": "Evaluasi Kinerja (Performance Appraisal)"}, {"key": "D", "text": "Perencanaan Karir"}]'::jsonb,'A','Ini adalah definisi dari evaluasi kinerja, sebuah proses formal untuk meninjau dan menilai kinerja karyawan. Hasilnya digunakan untuk keputusan promosi, kebutuhan pelatihan, dan penetapan bonus.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menurut teori dua faktor Herzberg, gaji, kondisi kerja, dan keamanan kerja di PLN termasuk dalam kategori...','[{"key": "A", "text": "Faktor Motivator"}, {"key": "B", "text": "Faktor Higienis (Hygiene Factors)"}, {"key": "C", "text": "Faktor Aktualisasi Diri"}, {"key": "D", "text": "Faktor Sosial"}]'::jsonb,'A','Menurut Teori Dua Faktor Herzberg, faktor higienis adalah faktor ekstrinsik yang diperlukan untuk mencegah ketidakpuasan, tetapi tidak serta-merta menciptakan kepuasan atau motivasi. Contoh lainnya termasuk kebijakan perusahaan dan hubungan dengan atasan.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN mengadakan program pelatihan "K2/K3" (Keselamatan dan Kesehatan Kerja) bagi teknisi lapangan. Tujuan utama dari pelatihan ini adalah...','[{"key": "A", "text": "Meningkatkan kepuasan kerja"}, {"key": "B", "text": "Mengurangi risiko kecelakaan kerja dan meningkatkan kompetensi"}, {"key": "C", "text": "Mempersiapkan promosi jabatan"}, {"key": "D", "text": "Memenuhi kebutuhan sosial karyawan"}]'::jsonb,'A','Pelatihan K3 secara langsung bertujuan untuk meningkatkan kesadaran, pengetahuan, dan keterampilan teknis karyawan dalam menjaga keselamatan dan kesehatan di lingkungan kerja yang berisiko tinggi seperti instalasi listrik.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses menarik, menyeleksi, dan menempatkan orang yang berkualitas untuk suatu jabatan di perusahaan disebut...','[{"key": "A", "text": "Orientasi"}, {"key": "B", "text": "Rekrutmen"}, {"key": "C", "text": "Evaluasi"}, {"key": "D", "text": "Mutasi"}]'::jsonb,'A','Rekrutmen adalah serangkaian proses yang mencakup identifikasi kebutuhan tenaga kerja, pencarian kandidat (sourcing), seleksi (wawancara, tes), hingga penawaran kerja dan penempatan karyawan baru.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang karyawan PLN yang merasa kebutuhannya untuk dihargai dan diakui atas prestasinya telah terpenuhi, menurut hierarki kebutuhan Maslow, sedang berusaha memenuhi kebutuhan tingkat...','[{"key": "A", "text": "Fisiologis"}, {"key": "B", "text": "Keamanan"}, {"key": "C", "text": "Sosial"}, {"key": "D", "text": "Penghargaan (Esteem)"}]'::jsonb,'A','Menurut Hierarki Maslow, setelah kebutuhan fisiologis, keamanan, dan sosial terpenuhi, individu akan termotivasi oleh kebutuhan akan penghargaan. Ini mencakup kebutuhan internal (harga diri, prestasi) dan eksternal (pengakuan, status).','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Salah satu metode evaluasi kinerja dimana seorang karyawan dinilai oleh atasan, rekan kerja, bawahan, dan bahkan oleh dirinya sendiri dikenal sebagai...','[{"key": "A", "text": "Management by Objectives (MBO)"}, {"key": "B", "text": "360-Degree Feedback"}, {"key": "C", "text": "Critical Incident Method"}, {"key": "D", "text": "Graphic Rating Scale"}]'::jsonb,'A','Metode umpan balik 360 derajat mengumpulkan penilaian dari berbagai sumber yang berinteraksi dengan karyawan (atasan, rekan, bawahan). Tujuannya adalah memberikan gambaran kinerja yang lebih holistik dan mengurangi bias dari satu penilai saja.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang manajer di Unit Pelaksana Pelayanan Pelanggan (UP3) PLN sedang menyusun target pendapatan dan jumlah pelanggan yang akan dilayani untuk tahun depan. Kegiatan yang dilakukan manajer tersebut merupakan bagian dari fungsi manajemen...','[{"key": "A", "text": "Organizing (Pengorganisasian)"}, {"key": "B", "text": "Planning (Perencanaan)"}, {"key": "C", "text": "Controlling (Pengendalian)"}, {"key": "D", "text": "Leading (Kepemimpinan)"}]'::jsonb,'A','Menyusun target pendapatan, jumlah pelanggan baru, dan rencana pengembangan jaringan untuk tahun depan adalah esensi dari fungsi perencanaan (planning). Ini adalah langkah awal dan fundamental dalam manajemen di mana manajer menetapkan "apa" yang ingin dicapai dan "bagaimana" cara mencapainya.','AKDING',1);
