  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah unit proyek pembangunan transmisi baru di PLN terdiri dari insinyur, staf keuangan, dan ahli hukum yang melapor kepada manajer proyek dan juga kepada kepala departemen fungsional mereka masing-masing. Struktur organisasi yang paling sesuai untuk menggambarkan situasi ini adalah...','[{"key": "A", "text": "Struktur Fungsional"}, {"key": "B", "text": "Struktur Divisional"}, {"key": "C", "text": "Struktur Matriks"}, {"key": "D", "text": "Struktur Lini"}]'::jsonb,'A','Struktur matriks sering digunakan dalam organisasi berbasis proyek seperti PLN untuk pembangunan infrastruktur baru. Keuntungannya adalah fleksibilitas dan pemanfaatan ahli secara efisien lintas departemen, namun tantangan utamanya adalah potensi konflik karena karyawan memiliki dua atasan.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang pemimpin unit PLN yang cenderung mengambil keputusan sendiri tanpa banyak melibatkan bawahannya dan memberikan instruksi yang jelas untuk diikuti menerapkan gaya kepemimpinan...','[{"key": "A", "text": "Demokratis"}, {"key": "B", "text": "Otokratis"}, {"key": "C", "text": "Laissez-faire"}, {"key": "D", "text": "Transformasional"}]'::jsonb,'A','Gaya kepemimpinan otokratis (autocratic) adalah gaya di mana pemimpin membuat keputusan secara sepihak dengan sedikit atau tanpa masukan dari bawahan. Gaya ini bisa efektif dalam situasi darurat atau ketika keputusan cepat diperlukan, namun dalam jangka panjang dapat menurunkan motivasi dan kreativitas karyawan.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Gaya kepemimpinan yang berfokus pada pemberian inspirasi dan motivasi kepada karyawan untuk melampaui kepentingan pribadi demi kebaikan organisasi disebut...','[{"key": "A", "text": "Transaksional"}, {"key": "B", "text": "Transformasional"}, {"key": "C", "text": "Otokratis"}, {"key": "D", "text": "Demokratis"}]'::jsonb,'A','Pemimpin transformasional tidak hanya memberi perintah, tetapi juga bertindak sebagai panutan (role model) dan mentor. Mereka mendorong bawahan untuk melihat gambaran besar dan berkomitmen pada visi perusahaan, yang sangat penting di industri yang terus berkembang seperti ketenagalistrikan.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Di sebuah kantor layanan PLN yang situasinya dinamis dan membutuhkan keputusan cepat, manajer sering mengadakan rapat singkat untuk mendengar masukan dari tim sebelum mengambil keputusan akhir. Gaya kepemimpinan ini adalah...','[{"key": "A", "text": "Otokratis"}, {"key": "B", "text": "Laissez-faire"}, {"key": "C", "text": "Demokratis"}, {"key": "D", "text": "Karismatik"}]'::jsonb,'A','Dalam gaya demokratis, pemimpin tetap memegang tanggung jawab akhir atas keputusan, tetapi ia secara aktif mencari masukan dan ide dari anggota tim. Pendekatan ini dapat meningkatkan kualitas keputusan dan komitmen tim terhadap hasil akhir karena merasa dilibatkan.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kelemahan utama dari struktur organisasi fungsional adalah...','[{"key": "A", "text": "Kurangnya spesialisasi"}, {"key": "B", "text": "Kesulitan dalam koordinasi antar departemen"}, {"key": "C", "text": "Duplikasi sumber daya"}, {"key": "D", "text": "Rantai komando yang tidak jelas"}]'::jsonb,'A','Meskipun struktur fungsional (misalnya, departemen Keuangan, SDM, Teknik) mendorong spesialisasi yang mendalam, kelemahannya yang paling signifikan adalah "efek silo". Ini terjadi ketika departemen menjadi terlalu terisolasi dan kurang berkomunikasi satu sama lain, sehingga memperlambat proses yang membutuhkan kerjasama lintas-departemen.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menurut teori kepemimpinan situasional, pendekatan yang paling efektif bagi seorang pemimpin adalah...','[{"key": "A", "text": "Menggunakan satu gaya kepemimpinan secara konsisten"}, {"key": "B", "text": "Menyesuaikan gaya kepemimpinan dengan tingkat kesiapan (maturity) bawahan"}, {"key": "C", "text": "Berfokus sepenuhnya pada tugas (task-oriented)"}, {"key": "D", "text": "Berfokus sepenuhnya pada hubungan (relationship-oriented)"}]'::jsonb,'A','Teori ini menyarankan pemimpin untuk fleksibel. Misalnya, seorang teknisi baru mungkin membutuhkan gaya yang lebih mengarahkan (directing), sementara seorang insinyur senior yang berpengalaman mungkin lebih cocok dengan gaya mendelegasikan (delegating). Kunci efektivitasnya adalah diagnosis yang akurat terhadap tingkat kompetensi dan komitmen bawahan.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN membagi organisasinya berdasarkan wilayah geografis seperti Unit Induk Wilayah (UIW) Sumatera Barat, UIW Jawa Barat, dan seterusnya. Ini adalah contoh penerapan struktur organisasi...','[{"key": "A", "text": "Fungsional"}, {"key": "B", "text": "Matriks"}, {"key": "C", "text": "Divisional berdasarkan geografis"}, {"key": "D", "text": "Produk"}]'::jsonb,'A','Struktur divisional berdasarkan geografis seperti Unit Induk Wilayah (UIW) di PLN memungkinkan perusahaan untuk lebih responsif terhadap kebutuhan dan kondisi pasar lokal. Setiap divisi beroperasi seolah-olah bisnis kecil yang fokus pada wilayahnya, sehingga lebih lincah dalam pengambilan keputusan yang relevan dengan area tersebut.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses sistematis untuk mengumpulkan, menganalisis, dan mengevaluasi kinerja seorang karyawan terhadap standar pekerjaan yang telah ditetapkan di PLN disebut...','[{"key": "A", "text": "Rekrutmen"}, {"key": "B", "text": "Pelatihan dan Pengembangan"}, {"key": "C", "text": "Evaluasi Kinerja (Performance Appraisal)"}, {"key": "D", "text": "Perencanaan Karir"}]'::jsonb,'A','Ini adalah definisi dari evaluasi kinerja, sebuah proses formal untuk meninjau dan menilai kinerja karyawan. Hasilnya digunakan untuk keputusan promosi, kebutuhan pelatihan, dan penetapan bonus.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menurut teori dua faktor Herzberg, gaji, kondisi kerja, dan keamanan kerja di PLN termasuk dalam kategori...','[{"key": "A", "text": "Faktor Motivator"}, {"key": "B", "text": "Faktor Higienis (Hygiene Factors)"}, {"key": "C", "text": "Faktor Aktualisasi Diri"}, {"key": "D", "text": "Faktor Sosial"}]'::jsonb,'A','Menurut Teori Dua Faktor Herzberg, faktor higienis adalah faktor ekstrinsik yang diperlukan untuk mencegah ketidakpuasan, tetapi tidak serta-merta menciptakan kepuasan atau motivasi. Contoh lainnya termasuk kebijakan perusahaan dan hubungan dengan atasan.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN mengadakan program pelatihan "K2/K3" (Keselamatan dan Kesehatan Kerja) bagi teknisi lapangan. Tujuan utama dari pelatihan ini adalah...','[{"key": "A", "text": "Meningkatkan kepuasan kerja"}, {"key": "B", "text": "Mengurangi risiko kecelakaan kerja dan meningkatkan kompetensi"}, {"key": "C", "text": "Mempersiapkan promosi jabatan"}, {"key": "D", "text": "Memenuhi kebutuhan sosial karyawan"}]'::jsonb,'A','Pelatihan K3 secara langsung bertujuan untuk meningkatkan kesadaran, pengetahuan, dan keterampilan teknis karyawan dalam menjaga keselamatan dan kesehatan di lingkungan kerja yang berisiko tinggi seperti instalasi listrik.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses menarik, menyeleksi, dan menempatkan orang yang berkualitas untuk suatu jabatan di perusahaan disebut...','[{"key": "A", "text": "Orientasi"}, {"key": "B", "text": "Rekrutmen"}, {"key": "C", "text": "Evaluasi"}, {"key": "D", "text": "Mutasi"}]'::jsonb,'A','Rekrutmen adalah serangkaian proses yang mencakup identifikasi kebutuhan tenaga kerja, pencarian kandidat (sourcing), seleksi (wawancara, tes), hingga penawaran kerja dan penempatan karyawan baru.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang karyawan PLN yang merasa kebutuhannya untuk dihargai dan diakui atas prestasinya telah terpenuhi, menurut hierarki kebutuhan Maslow, sedang berusaha memenuhi kebutuhan tingkat...','[{"key": "A", "text": "Fisiologis"}, {"key": "B", "text": "Keamanan"}, {"key": "C", "text": "Sosial"}, {"key": "D", "text": "Penghargaan (Esteem)"}]'::jsonb,'A','Menurut Hierarki Maslow, setelah kebutuhan fisiologis, keamanan, dan sosial terpenuhi, individu akan termotivasi oleh kebutuhan akan penghargaan. Ini mencakup kebutuhan internal (harga diri, prestasi) dan eksternal (pengakuan, status).','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Salah satu metode evaluasi kinerja dimana seorang karyawan dinilai oleh atasan, rekan kerja, bawahan, dan bahkan oleh dirinya sendiri dikenal sebagai...','[{"key": "A", "text": "Management by Objectives (MBO)"}, {"key": "B", "text": "360-Degree Feedback"}, {"key": "C", "text": "Critical Incident Method"}, {"key": "D", "text": "Graphic Rating Scale"}]'::jsonb,'A','Metode umpan balik 360 derajat mengumpulkan penilaian dari berbagai sumber yang berinteraksi dengan karyawan (atasan, rekan, bawahan). Tujuannya adalah memberikan gambaran kinerja yang lebih holistik dan mengurangi bias dari satu penilai saja.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pemberian bonus kinerja tahunan kepada karyawan PLN yang berhasil mencapai atau melampaui target adalah contoh penerapan teori motivasi...','[{"key": "A", "text": "Teori Harapan (Expectancy Theory)"}, {"key": "B", "text": "Teori Keadilan (Equity Theory)"}, {"key": "C", "text": "Teori Hierarki Kebutuhan"}, {"key": "D", "text": "Teori X dan Y"}]'::jsonb,'A','Teori Harapan menyatakan bahwa motivasi adalah hasil dari tiga faktor: Harapan (usaha akan menghasilkan kinerja), Instrumentality (kinerja akan diberi imbalan), dan Valence (nilai dari imbalan tersebut). Bonus kinerja menghubungkan langsung antara kinerja (mencapai target) dengan imbalan yang bernilai (uang).','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN sedang mengevaluasi proyek pembangunan pembangkit listrik tenaga surya. Metode penilaian investasi yang menghitung selisih antara nilai sekarang dari arus kas masuk dengan nilai sekarang dari biaya investasi adalah...','[{"key": "A", "text": "Internal Rate of Return (IRR)"}, {"key": "B", "text": "Payback Period"}, {"key": "C", "text": "Net Present Value (NPV)"}, {"key": "D", "text": "Profitability Index"}]'::jsonb,'A','NPV adalah metode superior dalam penganggaran modal karena mempertimbangkan nilai waktu dari uang (time value of money). Metode ini menghitung selisih antara nilai sekarang (present value) dari arus kas masuk dengan biaya awal investasi.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika sebuah proyek investasi di PLN memiliki nilai NPV positif (NPV > 0), maka proyek tersebut...','[{"key": "A", "text": "Harus ditolak karena tidak menguntungkan"}, {"key": "B", "text": "Sebaiknya diterima karena memberikan pengembalian lebih besar dari tingkat diskonto yang disyaratkan"}, {"key": "C", "text": "Hanya akan kembali modal tanpa keuntungan"}, {"key": "D", "text": "Memiliki tingkat pengembalian yang sama dengan biaya modal"}]'::jsonb,'A','NPV positif (NPV > 0) menandakan bahwa proyek tersebut diproyeksikan akan menghasilkan laba dan meningkatkan nilai perusahaan, karena tingkat pengembaliannya melebihi biaya modal atau tingkat pengembalian minimum yang diharapkan.','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tingkat diskonto (discount rate) yang membuat nilai NPV suatu proyek investasi sama dengan nol disebut...','[{"key": "A", "text": "Cost of Capital"}, {"key": "B", "text": "Net Present Value (NPV)"}, {"key": "C", "text": "Internal Rate of Return (IRR)"}, {"key": "D", "text": "Required Rate of Return"}]'::jsonb,'A','IRR adalah metrik yang menunjukkan persentase tingkat pengembalian (rate of return) yang sebenarnya dari sebuah proyek. Proyek umumnya diterima jika nilai IRR-nya lebih tinggi dari biaya modal (cost of capital) perusahaan.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Rasio keuangan yang digunakan untuk mengukur kemampuan perusahaan seperti PLN dalam memenuhi kewajiban jangka pendeknya adalah...','[{"key": "A", "text": "Debt to Equity Ratio"}, {"key": "B", "text": "Return on Asset (ROA)"}, {"key": "C", "text": "Current Ratio (Rasio Lancar)"}, {"key": "D", "text": "Gross Profit Margin"}]'::jsonb,'A','Current Ratio (dihitung dengan membagi Aset Lancar dengan Utang Lancar) adalah indikator likuiditas. Rasio di atas 1 menunjukkan bahwa perusahaan memiliki aset lancar yang cukup untuk menutupi kewajiban jangka pendeknya.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Aset lancar dikurangi utang lancar akan menghasilkan...','[{"key": "A", "text": "Total Aset"}, {"key": "B", "text": "Modal Kerja (Working Capital)"}, {"key": "C", "text": "Ekuitas"}, {"key": "D", "text": "Laba Ditahan"}]'::jsonb,'A','Modal kerja (Working Capital = Current Assets - Current Liabilities) adalah ukuran kesehatan keuangan jangka pendek dan efisiensi operasional perusahaan. Modal kerja positif sangat penting untuk operasional sehari-hari.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN mempertimbangkan untuk berinvestasi pada teknologi jaringan baru. Proyek A memiliki IRR 15% dan Proyek B memiliki IRR 12%. Jika biaya modal (cost of capital) perusahaan adalah 10%, maka...','[{"key": "A", "text": "Hanya Proyek A yang harus diterima"}, {"key": "B", "text": "Hanya Proyek B yang harus diterima"}, {"key": "C", "text": "Kedua proyek harus diterima"}, {"key": "D", "text": "Kedua proyek harus ditolak"}]'::jsonb,'A','Aturan keputusan untuk IRR adalah menerima proyek jika IRR lebih besar dari biaya modal (cost of capital) atau hurdle rate. Karena IRR kedua proyek (15% dan 12%) lebih tinggi dari biaya modal (10%), keduanya secara finansial layak untuk diterima.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Analisis yang membandingkan berbagai pos dalam laporan keuangan dari satu periode ke periode berikutnya disebut...','[{"key": "A", "text": "Analisis Rasio"}, {"key": "B", "text": "Analisis Common Size"}, {"key": "C", "text": "Analisis Tren (Horizontal)"}, {"key": "D", "text": "Analisis Vertikal"}]'::jsonb,'A','Analisis horizontal atau analisis tren membandingkan data laporan keuangan perusahaan (misalnya pendapatan atau laba) selama beberapa periode akuntansi untuk melihat pola pertumbuhan, penurunan, atau stabilitas dari waktu ke waktu.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN menawarkan layanan listrik prabayar (token) dan pascabayar. Upaya ini merupakan bagian dari strategi...','[{"key": "A", "text": "Segmentasi pasar"}, {"key": "B", "text": "Promosi"}, {"key": "C", "text": "Diferensiasi produk"}, {"key": "D", "text": "Penentuan harga"}]'::jsonb,'A','Dengan menawarkan pilihan layanan yang berbeda (prabayar dengan kontrol pemakaian dan pascabayar dengan kemudahan pembayaran bulanan), PLN melakukan diferensiasi produk untuk melayani kebutuhan dan preferensi segmen pelanggan yang berbeda.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Aplikasi PLN Mobile yang memudahkan pelanggan untuk membeli token, membayar tagihan, dan melaporkan gangguan adalah contoh penerapan strategi pemasaran dalam elemen...','[{"key": "A", "text": "Product (Produk/Layanan)"}, {"key": "B", "text": "Price (Harga)"}, {"key": "C", "text": "Place (Distribusi/Tempat)"}, {"key": "D", "text": "Promotion (Promosi)"}]'::jsonb,'A','Dalam bauran pemasaran, ''Place'' tidak hanya berarti lokasi fisik tetapi juga mencakup semua saluran distribusi dan aksesibilitas layanan. Aplikasi PLN Mobile berfungsi sebagai ''tempat'' atau saluran digital di mana pelanggan dapat dengan mudah berinteraksi dan bertransaksi dengan PLN.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kegiatan PLN yang membagi pasar pelanggannya menjadi beberapa kelompok, seperti pelanggan rumah tangga, bisnis, dan industri, disebut...','[{"key": "A", "text": "Positioning"}, {"key": "B", "text": "Segmentasi"}, {"key": "C", "text": "Targeting"}, {"key": "D", "text": "Marketing Mix"}]'::jsonb,'A','Segmentasi adalah langkah pertama dalam strategi pemasaran, yaitu proses membagi pasar yang luas dan heterogen menjadi kelompok-kelompok (segmen) yang lebih kecil dan homogen berdasarkan karakteristik tertentu (misalnya, jenis penggunaan, daya, lokasi).','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'"PLN berkomitmen untuk memberikan layanan listrik yang andal dan terjangkau bagi seluruh masyarakat Indonesia." Pernyataan ini mencerminkan upaya perusahaan dalam membangun...','[{"key": "A", "text": "Segmentasi pasar"}, {"key": "B", "text": "Target pasar"}, {"key": "C", "text": "Posisi (Positioning) di benak pelanggan"}, {"key": "D", "text": "Bauran promosi"}]'::jsonb,'A','Positioning adalah tentang menciptakan persepsi yang jelas dan unik tentang merek atau perusahaan di benak target pelanggan. Pernyataan tersebut adalah upaya PLN untuk memposisikan diri sebagai penyedia listrik yang andal dan terjangkau.','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Empat elemen utama dalam bauran pemasaran (Marketing Mix) yang dikenal sebagai 4P adalah...','[{"key": "A", "text": "People, Process, Product, Price"}, {"key": "B", "text": "Product, Price, Place, Promotion"}, {"key": "C", "text": "Planning, Price, People, Promotion"}, {"key": "D", "text": "Product, Planning, Place, Process"}]'::jsonb,'A','Ini adalah 4P klasik dari bauran pemasaran (marketing mix). Semua elemen ini harus dirancang secara terpadu untuk menciptakan strategi pemasaran yang efektif dan mencapai target pasar.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Program diskon tambah daya yang ditawarkan PLN pada hari-hari besar nasional adalah contoh strategi...','[{"key": "A", "text": "Pengembangan Produk"}, {"key": "B", "text": "Promosi Penjualan"}, {"key": "C", "text": "Hubungan Masyarakat"}, {"key": "D", "text": "Penetrasi Pasar"}]'::jsonb,'A','Promosi penjualan (sales promotion) adalah berbagai insentif jangka pendek yang dirancang untuk mendorong pembelian atau penjualan suatu produk atau jasa dengan lebih cepat. Diskon tambah daya adalah contoh taktik promosi penjualan.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Prinsip Good Corporate Governance (GCG) yang menuntut adanya kejelasan fungsi, pelaksanaan, dan pertanggungjawaban organ perusahaan sehingga pengelolaan berjalan efektif disebut...','[{"key": "A", "text": "Transparency (Keterbukaan)"}, {"key": "B", "text": "Accountability (Akuntabilitas)"}, {"key": "C", "text": "Responsibility (Pertanggungjawaban)"}, {"key": "D", "text": "Independency (Kemandirian)"}]'::jsonb,'A','Akuntabilitas adalah prinsip GCG yang memastikan adanya kejelasan fungsi, struktur, sistem, dan pertanggungjawaban organ perusahaan. Dengan akuntabilitas, kinerja perusahaan dapat diukur dan dipertanggungjawabkan secara transparan.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebagai BUMN, PLN wajib mengikuti prinsip-prinsip GCG. Prinsip yang menekankan bahwa perusahaan harus dikelola secara profesional tanpa benturan kepentingan dan pengaruh/tekanan dari pihak manapun adalah...','[{"key": "A", "text": "Fairness"}, {"key": "B", "text": "Accountability"}, {"key": "C", "text": "Responsibility"}, {"key": "D", "text": "Independency"}]'::jsonb,'A','Prinsip kemandirian (independency) mengharuskan BUMN dikelola secara profesional, tanpa adanya benturan kepentingan (conflict of interest) dan pengaruh atau tekanan dari pihak manapun yang tidak sesuai dengan peraturan perundangan.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dokumen yang menetapkan langkah-langkah kerja yang harus diikuti secara sistematis untuk menyelesaikan suatu proses kerja di PLN, misalnya proses penyambungan baru, disebut...','[{"key": "A", "text": "Job Description"}, {"key": "B", "text": "Company Regulation"}, {"key": "C", "text": "Standard Operating Procedure (SOP)"}, {"key": "D", "text": "Code of Conduct"}]'::jsonb,'A','SOP adalah dokumen yang berisi serangkaian instruksi tertulis yang dibakukan mengenai berbagai proses penyelenggaraan administrasi. Tujuannya adalah untuk memastikan konsistensi, efisiensi, dan mengurangi kesalahan dalam pelaksanaan tugas.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses evaluasi yang sistematis dan independen yang dilakukan oleh unit internal perusahaan untuk memastikan operasional berjalan sesuai aturan, efisien, dan efektif disebut...','[{"key": "A", "text": "Audit Eksternal"}, {"key": "B", "text": "Audit Internal"}, {"key": "C", "text": "Rapat Umum Pemegang Saham (RUPS)"}, {"key": "D", "text": "Penilaian Kinerja"}]'::jsonb,'A','Audit internal adalah kegiatan assurance dan konsultasi yang independen dan objektif, dirancang untuk memberi nilai tambah dan meningkatkan operasional perusahaan. Fungsi ini membantu manajemen mencapai tujuannya dengan evaluasi sistematis terhadap efektivitas manajemen risiko, pengendalian, dan proses tata kelola.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Prinsip GCG yang memperlakukan semua pemangku kepentingan (stakeholders) secara adil dan setara adalah...','[{"key": "A", "text": "Transparency"}, {"key": "B", "text": "Accountability"}, {"key": "C", "text": "Fairness (Kewajaran dan Kesetaraan)"}, {"key": "D", "text": "Responsibility"}]'::jsonb,'A','Prinsip fairness menuntut adanya perlakuan yang adil dan setara dalam memenuhi hak-hak pemangku kepentingan (stakeholders) yang timbul berdasarkan perjanjian dan peraturan. Ini mencakup perlindungan terhadap pemegang saham minoritas dan perlakuan yang adil kepada semua pelanggan.','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Etika pelayanan publik yang harus dijunjung tinggi oleh pegawai PLN antara lain, kecuali...','[{"key": "A", "text": "Memberikan layanan yang cepat dan tepat"}, {"key": "B", "text": "Bersikap ramah dan sopan kepada pelanggan"}, {"key": "C", "text": "Memberikan perlakuan khusus kepada kerabat atau teman"}, {"key": "D", "text": "Menjaga kerahasiaan data pelanggan"}]'::jsonb,'A','Memberikan perlakuan khusus atau preferensial kepada pihak tertentu karena hubungan pribadi (nepotisme/kolusi) secara fundamental bertentangan dengan prinsip keadilan (fairness), transparansi, dan profesionalisme yang merupakan pilar utama etika pelayanan publik.','AKDING',40);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang manajer unit pembangkitan PLN menetapkan Standar Kinerja Utama (KPI) terkait efisiensi bahan bakar dan jam operasional mesin. Setelah satu kuartal, ia membandingkan laporan aktual dengan KPI tersebut. Langkah pembandingan ini merupakan inti dari fungsi...','[{"key": "A", "text": "Planning"}, {"key": "B", "text": "Organizing"}, {"key": "C", "text": "Leading"}, {"key": "D", "text": "Controlling"}]'::jsonb,'A','Fungsi controlling (pengendalian) secara fundamental melibatkan tiga langkah: (1) Menetapkan standar atau KPI, (2) Mengukur kinerja aktual, dan (3) Membandingkan kinerja dengan standar untuk mengambil tindakan korektif. Langkah yang dijelaskan dalam soal adalah langkah kedua dan ketiga dari proses ini.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manajemen puncak PLN memutuskan strategi jangka panjang untuk beralih ke Energi Baru Terbarukan (EBT). Manajer di tingkat unit kemudian menerjemahkan strategi ini menjadi rencana-rencana operasional tahunan. Proses ini menunjukkan bahwa perencanaan bersifat...','[{"key": "A", "text": "Statis"}, {"key": "B", "text": "Hierarkis"}, {"key": "C", "text": "Terisolasi"}, {"key": "D", "text": "Reaktif"}]'::jsonb,'A','Perencanaan dalam organisasi besar seperti PLN bersifat hierarkis (bertingkat). Ada perencanaan strategis (jangka panjang, dibuat oleh manajemen puncak), yang kemudian dijabarkan menjadi perencanaan taktis (jangka menengah, oleh manajer menengah), dan akhirnya perencanaan operasional (jangka pendek, oleh manajer lini pertama).','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang supervisor teknisi lapangan melakukan delegasi wewenang kepada ketua tim untuk mengambil keputusan cepat saat terjadi gangguan ringan, tanpa harus selalu melapor kepadanya. Praktik ini merupakan contoh dari fungsi...','[{"key": "A", "text": "Planning"}, {"key": "B", "text": "Organizing"}, {"key": "C", "text": "Controlling"}, {"key": "D", "text": "Forecasting"}]'::jsonb,'A','Delegasi wewenang adalah bagian penting dari fungsi organizing. Ini adalah proses mengalokasikan wewenang formal dan tanggung jawab kepada bawahan. Tujuannya adalah untuk memberdayakan karyawan dan mempercepat pengambilan keputusan, sehingga organisasi lebih lincah dan efisien.','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam rapat tim, terjadi perbedaan pendapat yang tajam antara dua insinyur mengenai metode perbaikan jaringan. Manajer proyek kemudian menengahi, memfasilitasi diskusi, dan membantu tim mencapai konsensus. Kemampuan manajer ini adalah bagian krusial dari fungsi...','[{"key": "A", "text": "Leading"}, {"key": "B", "text": "Organizing"}, {"key": "C", "text": "Controlling"}, {"key": "D", "text": "Planning"}]'::jsonb,'A','Fungsi leading tidak hanya tentang memberi perintah, tetapi juga tentang mengelola dinamika tim. Menyelesaikan konflik, memfasilitasi komunikasi, dan membangun konsensus adalah keterampilan kepemimpinan interpersonal yang esensial untuk menjaga tim tetap solid dan produktif.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fungsi manajemen yang paling berfokus pada alokasi dan penataan sumber daya, baik manusia maupun material, untuk menjalankan rencana secara efisien adalah...','[{"key": "A", "text": "Planning"}, {"key": "B", "text": "Organizing"}, {"key": "C", "text": "Leading"}, {"key": "D", "text": "Controlling"}]'::jsonb,'A','Ini adalah definisi inti dari fungsi organizing. Setelah rencana (Planning) dibuat, manajer harus mengorganisir semua sumber daya yang ada—mengelompokkan pekerjaan, menugaskan orang, dan mengalokasikan peralatan—untuk memastikan rencana dapat diimplementasikan.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'"Umpan balik" (feedback) dari hasil pengawasan (controlling) sangat penting bagi fungsi perencanaan (planning) karena...','[{"key": "A", "text": "Umpan balik hanya berguna untuk menilai kinerja staf"}, {"key": "B", "text": "Umpan balik menjadi dasar untuk membuat perencanaan di siklus berikutnya agar lebih realistis dan efektif"}, {"key": "C", "text": "Umpan balik tidak memiliki kaitan dengan perencanaan"}, {"key": "D", "text": "Umpan balik hanya digunakan untuk menghukum karyawan yang tidak mencapai target"}]'::jsonb,'A','Manajemen adalah sebuah siklus. Hasil dari fungsi controlling (apa yang berhasil, apa yang gagal, mengapa ada penyimpangan) menjadi input yang sangat berharga untuk fungsi planning berikutnya. Tanpa umpan balik ini, perencanaan akan didasarkan pada asumsi, bukan data dan pengalaman nyata.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang manajer menetapkan tujuan, kemudian ia merancang struktur tim, selanjutnya ia memotivasi timnya, dan terakhir ia mengevaluasi kemajuan. Rangkaian aktivitas ini menggambarkan...','[{"key": "A", "text": "Proses Manajemen"}, {"key": "B", "text": "Analisis Jabatan"}, {"key": "C", "text": "Evaluasi Kinerja"}, {"key": "D", "text": "Budaya Organisasi"}]'::jsonb,'A','Rangkaian aktivitas yang disebutkan (menetapkan tujuan, merancang struktur, memotivasi, mengevaluasi) secara sempurna menggambarkan urutan logis dari fungsi-fungsi manajemen (Planning, Organizing, Leading, Controlling) yang membentuk sebuah proses berkelanjutan.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang manajer PLN percaya bahwa karyawannya pada dasarnya malas, tidak suka bekerja, dan harus diawasi dengan ketat. Pandangan ini sejalan dengan...','[{"key": "A", "text": "Teori Y McGregor"}, {"key": "B", "text": "Teori X McGregor"}, {"key": "C", "text": "Teori Kebutuhan Maslow"}, {"key": "D", "text": "Teori Dua Faktor Herzberg"}]'::jsonb,'A','Teori X mengasumsikan bahwa karyawan pada dasarnya negatif; mereka malas, menghindari tanggung jawab, dan perlu dipaksa untuk bekerja. Manajer dengan asumsi ini cenderung menerapkan gaya kepemimpinan yang otokratis dan pengawasan yang ketat.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Gaya kepemimpinan di mana pemimpin menetapkan tujuan yang menantang dan mengharapkan bawahan untuk berkinerja pada tingkat tertinggi mereka, sesuai dengan Teori Path-Goal, disebut...','[{"key": "A", "text": "Kepemimpinan Direktif"}, {"key": "B", "text": "Kepemimpinan Suportif"}, {"key": "C", "text": "Kepemimpinan Partisipatif"}, {"key": "D", "text": "Kepemimpinan Berorientasi Prestasi (Achievement-Oriented)"}]'::jsonb,'A','Menurut teori Path-Goal, pemimpin yang berorientasi pada prestasi menetapkan tujuan yang menantang, menunjukkan kepercayaan pada kemampuan bawahan, dan terus mencari peningkatan kinerja. Gaya ini efektif untuk tugas yang kompleks dan tidak terstruktur.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jumlah bawahan yang dapat diawasi secara efektif oleh seorang manajer disebut...','[{"key": "A", "text": "Rantai Komando"}, {"key": "B", "text": "Rentang Kendali (Span of Control)"}, {"key": "C", "text": "Sentralisasi"}, {"key": "D", "text": "Desentralisasi"}]'::jsonb,'A','Rentang kendali menentukan berapa banyak bawahan yang melapor langsung ke seorang manajer. Rentang yang sempit menghasilkan struktur organisasi yang "tinggi" (tall) dengan banyak level manajemen, sedangkan rentang yang lebar menghasilkan struktur yang "datar" (flat).','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pemimpin yang memberikan penghargaan (misalnya bonus) untuk kinerja yang baik dan mengambil tindakan korektif untuk kinerja yang buruk menerapkan gaya kepemimpinan...','[{"key": "A", "text": "Transformasional"}, {"key": "B", "text": "Transaksional"}, {"key": "C", "text": "Laissez-faire"}, {"key": "D", "text": "Karismatik"}]'::jsonb,'A','Kepemimpinan transaksional berfokus pada pertukaran (transaksi) antara pemimpin dan bawahan. Pemimpin mengklarifikasi peran dan tugas, serta memberikan imbalan kontingen berdasarkan pencapaian target. Ini berbeda dengan kepemimpinan transformasional yang berfokus pada inspirasi dan visi.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Budaya organisasi yang kuat di PLN, yang menekankan pada integritas dan pelayanan pelanggan, berfungsi sebagai...','[{"key": "A", "text": "Pengganti struktur formal"}, {"key": "B", "text": "Mekanisme kontrol sosial dan panduan perilaku karyawan"}, {"key": "C", "text": "Penyebab utama konflik antar karyawan"}, {"key": "D", "text": "Hambatan untuk mencapai tujuan perusahaan"}]'::jsonb,'A','Budaya organisasi yang kuat bertindak sebagai "perekat sosial" yang menyatukan anggota. Ini menciptakan pemahaman bersama tentang "cara kita melakukan sesuatu di sini", yang secara implisit memandu perilaku dan keputusan karyawan bahkan tanpa pengawasan langsung.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses di mana karyawan baru mempelajari dan beradaptasi dengan nilai-nilai, norma, dan pola perilaku yang berlaku di PLN disebut...','[{"key": "A", "text": "Seleksi"}, {"key": "B", "text": "Sosialisasi Organisasi"}, {"key": "C", "text": "Analisis Jabatan"}, {"key": "D", "text": "Rotasi Jabatan"}]'::jsonb,'A','Sosialisasi adalah proses adaptasi di mana individu berubah dari orang luar menjadi anggota internal yang berfungsi. Melalui orientasi, pelatihan, dan interaksi, karyawan baru mempelajari nilai-nilai dan norma-norma yang penting untuk keberhasilan di dalam organisasi.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam sebuah unit PLN, meskipun ada struktur organisasi formal, para karyawan sering berinteraksi dan membentuk kelompok berdasarkan kesamaan hobi atau asal daerah. Interaksi ini membentuk...','[{"key": "A", "text": "Organisasi Formal"}, {"key": "B", "text": "Organisasi Informal"}, {"key": "C", "text": "Struktur Matriks"}, {"key": "D", "text": "Birokrasi"}]'::jsonb,'A','Organisasi informal muncul secara spontan dari interaksi sosial antar karyawan. Meskipun tidak digambarkan dalam bagan struktur resmi, jaringan informal ini bisa sangat berpengaruh terhadap aliran informasi, pembentukan opini, dan bahkan produktivitas.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN mengidentifikasi beberapa manajer berpotensi tinggi dan mempersiapkan mereka melalui pelatihan khusus untuk mengisi posisi-posisi kunci di masa depan. Kegiatan ini disebut...','[{"key": "A", "text": "Rekrutmen Eksternal"}, {"key": "B", "text": "Perencanaan Suksesi (Succession Planning)"}, {"key": "C", "text": "Orientasi Karyawan"}, {"key": "D", "text": "Pemutusan Hubungan Kerja"}]'::jsonb,'A','Perencanaan suksesi adalah proses proaktif untuk memastikan kelangsungan kepemimpinan di semua posisi kunci. Ini melibatkan identifikasi dan pengembangan bakat internal untuk memastikan transisi yang mulus ketika seorang pejabat pensiun atau pindah.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses sistematis untuk menentukan tugas, kewajiban, dan tanggung jawab dari suatu jabatan, serta pengetahuan dan keterampilan yang dibutuhkan untuk melakukannya, disebut...','[{"key": "A", "text": "Analisis Jabatan (Job Analysis)"}, {"key": "B", "text": "Evaluasi Kinerja"}, {"key": "C", "text": "Desain Pekerjaan"}, {"key": "D", "text": "Rotasi Pekerjaan"}]'::jsonb,'A','Analisis jabatan adalah landasan bagi hampir semua fungsi SDM. Hasilnya (berupa Job Description dan Job Specification) digunakan untuk rekrutmen, penetapan kompensasi, evaluasi kinerja, dan penentuan kebutuhan pelatihan.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pelatihan di mana seorang teknisi junior belajar langsung dengan mendampingi teknisi senior di lapangan saat melakukan pemeliharaan trafo adalah contoh metode...','[{"key": "A", "text": "Pelatihan di luar pekerjaan (Off-the-job training)"}, {"key": "B", "text": "Pelatihan di tempat kerja (On-the-job training)"}, {"key": "C", "text": "Simulasi"}, {"key": "D", "text": "Studi Kasus"}]'::jsonb,'A','Metode ini (sering disebut OJT) melibatkan pembelajaran dengan melakukan pekerjaan secara langsung di lingkungan kerja nyata, biasanya di bawah bimbingan seorang mentor atau karyawan senior. Ini sangat efektif untuk pekerjaan yang bersifat teknis dan praktis.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Menurut Teori Keadilan (Equity Theory), seorang karyawan akan merasa termotivasi jika...','[{"key": "A", "text": "Ia menerima gaji tertinggi di perusahaan"}, {"key": "B", "text": "Ia merasa rasio antara input (usaha) dan output (gaji, bonus) yang ia terima sebanding dengan rasio rekan kerjanya"}, {"key": "C", "text": "Ia hanya fokus pada imbalan yang ia terima tanpa membandingkan dengan orang lain"}, {"key": "D", "text": "Atasannya selalu memberikan pujian"}]'::jsonb,'A','Teori Keadilan menyatakan bahwa motivasi dipengaruhi oleh persepsi karyawan tentang seberapa adil mereka diperlakukan dibandingkan dengan orang lain. Ketidakadilan yang dirasakan (baik dibayar lebih rendah maupun lebih tinggi untuk pekerjaan yang sama) dapat menyebabkan demotivasi.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tahap pertama dalam proses rekrutmen yang efektif adalah...','[{"key": "A", "text": "Memasang iklan lowongan"}, {"key": "B", "text": "Melakukan wawancara"}, {"key": "C", "text": "Mengidentifikasi kebutuhan jabatan (perencanaan SDM)"}, {"key": "D", "text": "Melakukan tes psikologi"}]'::jsonb,'A','Sebelum mencari kandidat, langkah paling awal dan krusial adalah memahami dengan jelas jabatan apa yang dibutuhkan, mengapa dibutuhkan, dan kualifikasi apa yang diperlukan. Tanpa langkah ini, proses rekrutmen akan kehilangan arah dan tidak efektif.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dokumen yang menguraikan tugas-tugas, tanggung jawab, dan kondisi kerja dari suatu jabatan adalah...','[{"key": "A", "text": "Spesifikasi Jabatan (Job Specification)"}, {"key": "B", "text": "Deskripsi Jabatan (Job Description)"}, {"key": "C", "text": "SOP"}, {"key": "D", "text": "Kontrak Kerja"}]'::jsonb,'A','Deskripsi Jabatan (Job Description) adalah dokumen yang berfokus pada pekerjaan itu sendiri; merinci tugas, tanggung jawab, dan wewenang. Sementara itu, Spesifikasi Jabatan (Job Specification) berfokus pada orangnya; merinci kualifikasi (pendidikan, pengalaman) yang dibutuhkan.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sistem kompensasi yang diberikan PLN tidak hanya berupa gaji pokok, tetapi juga tunjangan kesehatan, dana pensiun, dan asuransi. Kumpulan imbalan ini disebut...','[{"key": "A", "text": "Gaji"}, {"key": "B", "text": "Upah"}, {"key": "C", "text": "Insentif"}, {"key": "D", "text": "Manfaat dan Tunjangan (Benefits)"}]'::jsonb,'A','Kompensasi total seorang karyawan terdiri dari kompensasi finansial langsung (gaji, bonus) dan kompensasi tidak langsung (manfaat dan tunjangan). Benefits seperti asuransi dan dana pensiun adalah bagian penting untuk menarik dan mempertahankan talenta.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah proyek pembangunan gardu induk memerlukan investasi awal Rp 1 Miliar dan diharapkan menghasilkan arus kas bersih Rp 250 Juta per tahun. Berapa Payback Period proyek tersebut?','[{"key": "A", "text": "3 tahun"}, {"key": "B", "text": "4 tahun"}, {"key": "C", "text": "5 tahun"}, {"key": "D", "text": "6 tahun"}]'::jsonb,'A','Payback Period adalah waktu yang dibutuhkan untuk mengembalikan investasi awal. Dihitung dengan: Investasi Awal / Arus Kas Bersih Tahunan = Rp 1.000.000.000 / Rp 250.000.000 = 4 tahun.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Rata-rata tertimbang dari biaya utang dan biaya ekuitas yang digunakan perusahaan untuk mendanai asetnya dikenal sebagai...','[{"key": "A", "text": "Internal Rate of Return (IRR)"}, {"key": "B", "text": "Weighted Average Cost of Capital (WACC)"}, {"key": "C", "text": "Return on Investment (ROI)"}, {"key": "D", "text": "Earnings Per Share (EPS)"}]'::jsonb,'A','WACC adalah biaya modal rata-rata perusahaan dari semua sumber pendanaan (utang, ekuitas). WACC sering digunakan sebagai tingkat diskonto (discount rate) dalam analisis NPV untuk proyek-proyek baru.','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika PLN ingin mengetahui seberapa besar laba yang dihasilkan dari setiap rupiah ekuitas yang diinvestasikan oleh pemegang saham, rasio yang paling tepat untuk digunakan adalah...','[{"key": "A", "text": "Return on Assets (ROA)"}, {"key": "B", "text": "Return on Equity (ROE)"}, {"key": "C", "text": "Debt to Equity Ratio"}, {"key": "D", "text": "Current Ratio"}]'::jsonb,'A','ROE (Laba Bersih / Total Ekuitas) adalah rasio profitabilitas utama yang mengukur seberapa efektif manajemen dalam menggunakan investasi dari pemegang saham untuk menghasilkan laba.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manajemen modal kerja (Working Capital Management) berkaitan dengan pengelolaan...','[{"key": "A", "text": "Aset tetap dan utang jangka panjang"}, {"key": "B", "text": "Aset lancar dan utang lancar"}, {"key": "C", "text": "Hanya kas dan setara kas"}, {"key": "D", "text": "Hanya investasi jangka panjang"}]'::jsonb,'A','Manajemen modal kerja berfokus pada pengelolaan pos-pos neraca jangka pendek, seperti kas, piutang, persediaan (aset lancar) dan utang usaha, utang jangka pendek (utang lancar), untuk memastikan likuiditas dan efisiensi operasional.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proyek X dan Proyek Y adalah dua proyek yang saling eksklusif (mutually exclusive). Jika terjadi konflik antara keputusan yang didasarkan pada NPV dan IRR, metode yang harus lebih diutamakan adalah...','[{"key": "A", "text": "IRR karena lebih mudah dipahami"}, {"key": "B", "text": "NPV karena mengasumsikan tingkat reinvestasi yang lebih realistis dan berfokus pada penambahan nilai absolut bagi perusahaan"}, {"key": "C", "text": "Keduanya sama-sama baik, bisa dipilih salah satu"}, {"key": "D", "text": "Payback Period karena paling sederhana"}]'::jsonb,'A','Dalam teori keuangan, NPV dianggap superior. NPV mengasumsikan arus kas diinvestasikan kembali pada tingkat biaya modal (WACC), yang lebih realistis daripada asumsi IRR yang diinvestasikan kembali pada tingkat IRR itu sendiri. Selain itu, NPV mengukur penambahan kekayaan dalam satuan mata uang absolut.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Analisis yang membandingkan setiap pos dalam laporan laba rugi terhadap total pendapatan disebut...','[{"key": "A", "text": "Analisis Horizontal"}, {"key": "B", "text": "Analisis Vertikal (Common-Size Analysis)"}, {"key": "C", "text": "Analisis Rasio"}, {"key": "D", "text": "Analisis Du Pont"}]'::jsonb,'A','Analisis vertikal menyajikan setiap pos laporan keuangan sebagai persentase dari sebuah basis. Untuk laporan laba rugi, basisnya adalah total pendapatan. Ini berguna untuk membandingkan kinerja antar periode atau antar perusahaan dengan ukuran yang berbeda.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kemampuan PLN untuk membayar bunga utang dan kewajiban tetap lainnya dapat diukur menggunakan...','[{"key": "A", "text": "Profit Margin"}, {"key": "B", "text": "Quick Ratio"}, {"key": "C", "text": "Times Interest Earned (TIE) Ratio"}, {"key": "D", "text": "Inventory Turnover"}]'::jsonb,'A','TIE Ratio (dihitung sebagai EBIT / Beban Bunga) adalah rasio solvabilitas yang mengukur kemampuan perusahaan untuk memenuhi kewajiban pembayaran bunganya. Rasio yang lebih tinggi menunjukkan posisi yang lebih aman.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN melakukan analisis internal untuk mengidentifikasi kekuatan (misalnya, jaringan distribusi yang luas) dan kelemahan (misalnya, beberapa pembangkit yang sudah tua), serta analisis eksternal untuk peluang dan ancaman. Analisis ini dikenal sebagai...','[{"key": "A", "text": "Analisis PESTLE"}, {"key": "B", "text": "Analisis SWOT"}, {"key": "C", "text": "Analisis Lima Kekuatan Porter"}, {"key": "D", "text": "Matriks BCG"}]'::jsonb,'A','Analisis SWOT adalah kerangka kerja strategis yang digunakan untuk mengevaluasi Strengths (Kekuatan), Weaknesses (Kelemahan), Opportunities (Peluang), dan Threats (Ancaman) yang dihadapi perusahaan.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam konteks pemasaran jasa (7P), keramahan dan kompetensi petugas layanan pelanggan PLN di kantor pelayanan termasuk dalam elemen...','[{"key": "A", "text": "Process"}, {"key": "B", "text": "Physical Evidence"}, {"key": "C", "text": "People"}, {"key": "D", "text": "Promotion"}]'::jsonb,'A','Dalam bauran pemasaran jasa (7P), elemen ''People'' merujuk pada semua sumber daya manusia yang terlibat dalam penyampaian layanan dan dapat memengaruhi persepsi pembeli. Ini termasuk sikap, penampilan, dan keterampilan staf.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Strategi PLN untuk meningkatkan penjualan layanan listrik kepada pelanggan yang sudah ada (misalnya, program tambah daya untuk rumah tangga) adalah contoh dari...','[{"key": "A", "text": "Pengembangan Pasar (Market Development)"}, {"key": "B", "text": "Pengembangan Produk (Product Development)"}, {"key": "C", "text": "Penetrasi Pasar (Market Penetration)"}, {"key": "D", "text": "Diversifikasi"}]'::jsonb,'A','Strategi penetrasi pasar berfokus pada upaya menjual lebih banyak produk yang ada ke pasar yang ada. Program tambah daya atau promo token listrik adalah cara untuk meningkatkan konsumsi (penjualan) di basis pelanggan yang sudah ada.','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Penggunaan aplikasi PLN Mobile untuk mencatat riwayat pemakaian, preferensi pembayaran, dan keluhan pelanggan adalah bagian dari implementasi...','[{"key": "A", "text": "Customer Relationship Management (CRM)"}, {"key": "B", "text": "Supply Chain Management (SCM)"}, {"key": "C", "text": "Enterprise Resource Planning (ERP)"}, {"key": "D", "text": "Total Quality Management (TQM)"}]'::jsonb,'A','CRM adalah strategi dan teknologi untuk mengelola semua interaksi dan hubungan perusahaan dengan pelanggan dan calon pelanggan. Tujuannya adalah untuk meningkatkan hubungan bisnis, membantu retensi pelanggan, dan mendorong pertumbuhan penjualan.','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Citra dan persepsi positif yang melekat pada nama dan logo PLN di benak masyarakat merupakan aset tak berwujud yang disebut...','[{"key": "A", "text": "Pangsa Pasar (Market Share)"}, {"key": "B", "text": "Ekuitas Merek (Brand Equity)"}, {"key": "C", "text": "Keunggulan Kompetitif"}, {"key": "D", "text": "Loyalitas Pelanggan"}]'::jsonb,'A','Ekuitas merek adalah nilai tambah yang diberikan oleh sebuah nama merek kepada suatu produk atau layanan. Merek yang kuat seperti PLN memiliki tingkat kesadaran dan loyalitas pelanggan yang tinggi, yang merupakan aset berharga.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Strategi generik Porter yang berfokus pada upaya untuk menjadi produsen dengan biaya terendah di industrinya adalah...','[{"key": "A", "text": "Diferensiasi"}, {"key": "B", "text": "Fokus"}, {"key": "C", "text": "Keunggulan Biaya (Cost Leadership)"}, {"key": "D", "text": "Inovasi"}]'::jsonb,'A','Menurut Michael Porter, strategi keunggulan biaya bertujuan untuk mencapai biaya produksi dan distribusi terendah sehingga perusahaan dapat menawarkan harga lebih rendah dari pesaing dan memenangkan pangsa pasar yang besar.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam struktur GCG di BUMN seperti PLN, pihak yang bertanggung jawab utama untuk melakukan pengawasan atas kebijakan direksi dan memberikan nasihat adalah...','[{"key": "A", "text": "Direksi"}, {"key": "B", "text": "Rapat Umum Pemegang Saham (RUPS)"}, {"key": "C", "text": "Dewan Komisaris"}, {"key": "D", "text": "Komite Audit"}]'::jsonb,'A','Dalam struktur perseroan terbatas, termasuk BUMN, Dewan Komisaris memiliki tugas utama melakukan pengawasan (supervisi) secara umum dan/atau khusus sesuai dengan anggaran dasar serta memberi nasihat kepada Direksi demi kepentingan perusahaan.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Program penanaman pohon di sekitar area pembangkit listrik atau penyediaan listrik gratis untuk sekolah di daerah terpencil adalah wujud dari prinsip GCG...','[{"key": "A", "text": "Transparency"}, {"key": "B", "text": "Accountability"}, {"key": "C", "text": "Responsibility (termasuk Tanggung Jawab Sosial & Lingkungan/CSR)"}, {"key": "D", "text": "Independency"}]'::jsonb,'A','Prinsip Responsibility menekankan bahwa perusahaan harus mematuhi peraturan perundangan dan melaksanakan tanggung jawabnya terhadap masyarakat dan lingkungan. Kegiatan CSR (Corporate Social Responsibility) adalah implementasi nyata dari prinsip ini.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN menyediakan saluran khusus bagi karyawan atau masyarakat untuk melaporkan dugaan pelanggaran etika atau hukum secara anonim dan aman. Sistem ini dikenal sebagai...','[{"key": "A", "text": "Sistem Audit Internal"}, {"key": "B", "text": "Whistleblowing System"}, {"key": "C", "text": "Sistem Manajemen Kinerja"}, {"key": "D", "text": "Standar Prosedur Operasi"}]'::jsonb,'A','Sistem ini merupakan bagian penting dari GCG yang dirancang untuk mendeteksi pelanggaran secara dini. Ini memberikan mekanisme pelaporan yang aman bagi siapa saja yang mengetahui adanya fraud, korupsi, atau perilaku tidak etis lainnya di dalam perusahaan.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perbedaan utama antara auditor internal dan auditor eksternal adalah...','[{"key": "A", "text": "Auditor eksternal adalah karyawan perusahaan, sedangkan auditor internal independen"}, {"key": "B", "text": "Auditor internal fokus pada kepatuhan dan efisiensi operasional untuk manajemen, sedangkan auditor eksternal fokus pada kewajaran laporan keuangan untuk pihak luar"}, {"key": "C", "text": "Hanya auditor eksternal yang melapor ke Direksi"}, {"key": "D", "text": "Auditor internal hanya memeriksa data keuangan"}]'::jsonb,'A','Ini adalah perbedaan fundamental. Auditor internal bekerja untuk perusahaan dan membantu manajemen meningkatkan proses internal. Auditor eksternal adalah pihak independen yang disewa untuk memberikan opini apakah laporan keuangan perusahaan bebas dari salah saji material, demi kepentingan investor dan kreditur.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebagai BUMN, kepemilikan saham mayoritas PLN dipegang oleh...','[{"key": "A", "text": "Publik melalui bursa efek"}, {"key": "B", "text": "Perusahaan swasta nasional"}, {"key": "C", "text": "Pemerintah Republik Indonesia"}, {"key": "D", "text": "Koperasi Karyawan"}]'::jsonb,'A','BUMN (Badan Usaha Milik Negara) adalah badan usaha yang seluruh atau sebagian besar modalnya dimiliki oleh negara melalui penyertaan secara langsung yang berasal dari kekayaan negara yang dipisahkan. Dalam hal PLN (Persero), 100% sahamnya dimiliki oleh Pemerintah RI.','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Salah satu tujuan utama penerapan Good Corporate Governance (GCG) di BUMN adalah...','[{"key": "A", "text": "Memaksimalkan gaji direksi dan komisaris"}, {"key": "B", "text": "Meningkatkan nilai perusahaan dan kepercayaan pemangku kepentingan (stakeholders)"}, {"key": "C", "text": "Mengurangi jumlah karyawan untuk efisiensi"}, {"key": "D", "text": "Menghindari pembayaran pajak kepada negara"}]'::jsonb,'A','Tujuan akhir dari GCG adalah menciptakan nilai ekonomi jangka panjang yang berkelanjutan bagi perusahaan (peningkatan nilai) sambil memastikan kepentingan semua pemangku kepentingan (pemegang saham, karyawan, pelanggan, masyarakat) terlindungi dan terpenuhi.','AKDING',40);
